(function(){
let signature='',chosen={exposure:0,estate:0};const money=n=>fmt(n)+' 萬';
const labels={borrow:'新增借款',buy:'新增買股',repay:'償還借款',drop:'模擬股票下跌（%）',otherAssets:'其他遺產課稅價值',gifts:'死亡前兩年依法併入的贈與',otherDebt:'其他可證明債務',children:'直系卑親屬人數',minorYears:'未成年卑親屬距成年年數合計',parents:'父母人數（0–2）',disability:'符合重度身心障礙扣除人數',otherDeductions:'其他依法可扣除金額',credits:'可扣抵稅額'};
function card(title,value){return `<div><span>${title}</span><strong>${value}</strong></div>`;}
function profile(m){return m.planning||(m.planning=RiskPlanning.normalize());}
function form(group){const m=family[chosen[group]??0],x=profile(m)[group];return `<h2>${group==='exposure'?'借款與股票曝險模擬':'2026 年遺產稅試算'}</h2><label>查閱成員<select data-plan-member="${group}">${family.map((m,i)=>`<option value="${i}" ${chosen[group]===i?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><p class="hint">金額單位：萬元${group==='exposure'?' · 模擬不改動實際部位':' · 依已填家庭資料計算，適用境內居住國民'}</p><div class="fields">${Object.keys(labels).filter(k=>k in x).map(k=>`<label>${labels[k]}<input type="number" min="0" ${k==='drop'?'max="100"':''} data-plan-group="${group}" data-plan-key="${k}" value="${x[k]}" step="${['children','minorYears','parents','disability'].includes(k)?'1':'0.01'}"></label>`).join('')}</div>${group==='estate'?`<label><input type="checkbox" data-plan-group="estate" data-plan-key="spouse" ${x.spouse?'checked':''}>有配偶（扣除 553 萬）</label><label><input type="checkbox" data-plan-group="estate" data-plan-key="provenDebt" ${x.provenDebt?'checked':''}>帳上借款有證明，可列債務扣除</label>`:'<button id="resetExposure">重設模擬</button>'}`;}
function render(rebuild=false){const key=JSON.stringify(family.map(m=>[m.name,m.data.pools.map(p=>p.name)]));if(rebuild||key!==signature){signature=key;for(const g of ['exposure','estate']){chosen[g]=Math.min(chosen[g],family.length-1);$(g+'Inputs').innerHTML=form(g);}$('interestInputs').innerHTML='<h2>每半年質押利息準備</h2><p class="hint">年利率請依契約填寫；半年利息按本金 × 年利率 ÷ 2 估算，不含手續費。</p><div class="tablewrap"><table><thead><tr><th>成員／券商</th><th>質押借款（萬）</th><th>年利率（%）</th><th>半年利息（萬）</th></tr></thead><tbody>'+family.flatMap((m,i)=>m.data.pools.map((p,j)=>p.pledgeDebt>0?`<tr><td>${esc(m.name)}／${esc(p.name)}</td><td>${fmt(p.pledgeDebt)}</td><td><input aria-label="${esc(m.name)} ${esc(p.name)} 質押年利率" data-interest-member="${i}" data-interest-pool="${j}" type="number" min="0" max="100" step="0.01" placeholder="填入利率" value="${p.pledgeRate??''}"></td><td id="interestCell${i}_${j}"></td></tr>`:'')).join('')+'</tbody></table></div>';}
$('interestResults').innerHTML='<div class="memberCards">'+family.map((m,i)=>{const ps=m.data.pools.filter(p=>p.pledgeDebt>0),missing=ps.filter(p=>RiskPlanning.interest(p)===null).length,total=ps.reduce((n,p)=>n+(RiskPlanning.interest(p)??0),0),principal=ps.reduce((n,p)=>n+Math.max(0,p.pledgeDebt-p.pledgeValue/1.66),0);m.data.pools.forEach((p,j)=>{const cell=$('interestCell'+i+'_'+j);if(cell)cell.textContent=RiskPlanning.interest(p)===null?'待填':fmt(RiskPlanning.interest(p));});return `<article class="memberCard"><h3>${esc(m.name)}</h3><div class="summary">${card('半年利息'+(missing?'（已填部分）':''),money(total))}${card('每月預留',money(total/6))}${card('可用現金',money(m.data.cash))}${card('利息現金缺口',missing?'尚待利率資料':money(Math.max(0,total-m.data.cash)))}</div><p>${missing?missing+' 筆尚未填利率 · ':''}另列展延補本金至166%：${money(principal)}</p></article>`;}).join('')+'</div><p class="hint">補本金與利息分開列示；實際展延資格與計息天數依契約確認。</p>';
for(const g of ['exposure','estate']){try{const m=family[chosen[g]],x=RiskPlanning.normalize(profile(m))[g];if(g==='exposure'){const r=RiskPlanning.exposure(m.data,x),base=RiskEngine.calculate(m.data);$('exposureResults').innerHTML='<h3>模擬結果</h3><div class="summary">'+card('股票市值',money(r.stock))+card('可用現金',money(r.cash))+card('總借款',money(r.debt))+card('目前 → 模擬曝險',fmt(base.leverage)+' → '+(r.leverage===null?'淨資產非正':fmt(r.leverage)+' 倍'))+card('模擬前淨資產',money(r.equity))+card('下跌 '+pct(x.drop)+' 後淨資產',money(r.stressed))+card('股票損失',money(r.loss))+card('股票跌10%／淨資產減少',r.leverage===null?'—':pct(r.leverage*10))+'</div><p class="hint">曝險越高，淨資產對股價波動越敏感；維持率與可扛跌幅請看資產儀表板。</p>';}else{const r=RiskPlanning.estate(m.data,x);$('estateResults').innerHTML='<h3>'+esc(m.name)+' · 個人稅額估算</h3><div class="summary">'+card('遺產總額',money(r.gross))+card('免稅額',money(1333))+card('扣除合計（含喪葬138萬）',money(r.deductions))+card('課稅遺產淨額',money(r.taxable))+card('估計遺產稅',money(r.tax))+card('帳面現金與稅額差額',money(m.data.cash-r.tax))+'</div><p class="hint">現有股票按目前市值估算；正式申報按繼承日課稅價值。其他扣除可填扶養親屬、配偶剩餘財產差額等合法項目，避免重複計入。</p><details><summary>2026 稅率與來源</summary><p>課稅淨額 ≤5,621萬：10%；≤11,242萬：15%減281.05萬；以上：20%減843.15萬。</p><a target="_blank" rel="noopener" href="https://www.ntbna.gov.tw/singlehtml/374fe8c4b18e48c691a6806ac02b9984?cntId=8236871cbd7e4b5686bd700f59fb1429">國稅局115年度免稅及扣除額</a> · <a target="_blank" rel="noopener" href="https://www.etax.nat.gov.tw/etwmain/tax-info/understanding/tax-q-and-a/national/estate-tax/payable/aYEGrlw">財政部稅額計算</a></details>';}}catch(e){$(g+'Results').textContent=e.message;}}
}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.interestMember!==undefined){const p=family[+t.dataset.interestMember].data.pools[+t.dataset.interestPool];if(t.value==='')delete p.pledgeRate;else p.pledgeRate=Number(t.value);mark();render();}if(t.dataset.planGroup){profile(family[chosen[t.dataset.planGroup]])[t.dataset.planGroup][t.dataset.planKey]=t.type==='checkbox'?t.checked:Number(t.value);mark();render();}});
document.addEventListener('change',e=>{if(e.target.dataset.planMember){chosen[e.target.dataset.planMember]=+e.target.value;render(true);}});
document.addEventListener('click',e=>{if(e.target.id==='resetExposure'){profile(family[chosen.exposure]).exposure=RiskPlanning.normalize().exposure;mark();render(true);}});
window.RiskExtras={render};for(const g of ['interest','exposure','estate'])$(g+'Tab').onclick=()=>showPage(g);render(true);
})();
